import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text())
done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[
dict(components=['6141','6141'],gloss=['give!','give!, he gave','give!; he gave','Give! / (He) gave','give'],forms=['dedɔ','dedɛ','dɛdɛ','dede','dedo','dedæ','de de','dedde'],citation='CDIAL[6141];platts1884[s.v. denā, de-denā]',evidence='Platts explicitly records de-denā as a compound giving verb. These affirmative imperative responses consist of de “give” plus the give auxiliary, inflected as de/do, so the same lexical family occurs twice in distinct ordered positions. CDIAL 6141 explains the de stem through MIA dēti and the imperative dēhi. The second occurrence is retained rather than deduplicated; mixed imperative/past responses are excluded from this group.'),
dict(components=['6141','6140-3'],gloss=['give!, he gave'],forms=['de dyɔ','dedīyɔ','dedyā','dɛdyo','dediyo'],citation='CDIAL[6141];CDIAL[6140,3];platts1884[s.v. denā, de-denā]',evidence='The complete response is de “give” plus diyā/diyo “gave” as perfective auxiliary. Platts documents de-denā; CDIAL 6141 supplies the first member and specifically 6140,3 *dita gives the second, including the contracted dyo form. Both components are represented in order; this is not an undivided descendant of either Sanskrit head.'),
dict(components=['8209','10948'],gloss=['drink!','drink!; he drank','Drink! / (He) drank','drink!, he drank'],forms=['pīlɛo','pīlo','pīlɛyo','pīleyo','pīle','pīlīyā','pīlyā','pile','pilyo','pilo','pilyā','pīlī','pīliyo','pīlīya'],citation='CDIAL[8209];CDIAL[10948];platts1884[s.v. pīnā, pī-lenā]',evidence='Platts explicitly records pī-lenā as an intensive drinking construction. The response contains the bare drink stem pī (CDIAL 8209) followed by take, either imperative le/lo or the liyo-type perfect recorded in CDIAL 10948. The take stem’s analogical history is retained in the primary evidence. Both lexical members receive ordered links; longer unanalysed auxiliaries and ambiguous plain pīla forms are excluded.'),
dict(components=['1200','10452'],gloss=['come!','come!, he came','come!; he came','Come! / (He) came'],forms=['ājā','ajā','aja','ājyā','ajyāo','ajao','ā jā','ā jyā'],citation='CDIAL[1200];CDIAL[10452];platts1884[s.v. ānā, ā-jānā]',evidence='The complete imperative response is ā “come” plus jā/jo “go” as auxiliary. Platts explicitly records ā-jānā; Turner places the regional ā/āv come stem under āpayati 1200 and jā under yāti 10452. Both ordered component families are represented. This follows Turner’s come-stem analysis rather than silently substituting the different āgata perfect stem or āgacchati family.'),
dict(components=['1200','4008'],gloss=['come!','come!, he came'],forms=['āgyā','āgyo','ā gayɔ','agya','agyā'],citation='CDIAL[1200];CDIAL[4008,1];platts1884[s.v. ānā, ā-jānā]',evidence='The surface response is ā “come” plus gyā/gyo/gayɔ “went” as perfective auxiliary. CDIAL 1200 supplies the first member, 4008,1 the contracted regional go perfect, and Platts records the ā-jānā construction. Even where the elicitation heading says “come!”, the actual perfect response is preserved and analysed. Responses with an additional āy/āi first member are excluded pending their own perfect-versus-conjunctive analysis.'),
dict(components=['8082','8209'],gloss=['to drink'],forms=['panī pīna','pani pina','pānī pīnā'],citation='CDIAL[8082];CDIAL[8209]',evidence='The whole elicited response literally contains water plus drink. CDIAL 8082 gives the regional pānī water noun and 8209 the pī drinking verb with its infinitive. Both lexical members are kept in source order; this is a modern noun–verb phrase, not a claim of an inherited Sanskrit compound.'),
dict(components=['8082','3865'],gloss=['to drink'],forms=['panikʰa','panikʰava','pani kʰa','pāni kʰā'],citation='CDIAL[8082];CDIAL[3865,1];platts1884[s.v. khānā]',evidence='This elicited drinking response literally combines pani “water” with the khā eat/consume verb. CDIAL 8082 supplies the water noun and 3865 the khā stem; the regional khānā construction also includes drinking in Platts. Both components are represented in their source order, including the ordinary verbal ending in khava; no auxiliary or noun is silently dropped.'),
]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms']:
   a.append(dict(record=r,components=g['components'],kind='component',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
(P/'pass010-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
held=[dict(record=r,candidates=['1200','10452'],reason='Marwari ājo may contain a polite ending rather than an independent go auxiliary; do not impose the ā+jā compound analysis without local grammatical evidence.') for r in rs if r['Form']=='ājo' and r['Gloss']=='come!, he came']
(P/'pass010-decisions.json').write_text(json.dumps({'accepted':a,'held':held},ensure_ascii=False,indent=1)+'\n')
print(len(a),[(g['components'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
